import './Main.css';
import Bar from './Bar.js'
import Question from './Question.js'
import Checker from './Checker.js'
import { useEffect, useMemo, useState, useTransition } from 'react';
function Main () {
    const [next, setNext] = useState(true);

    const [isMemorising, setIsMemorising] = useState(true);
    const toggleIsMemorising = () => {
        setIsMemorising(false);
    }

    const[checkAns, setCheckAns] = useState(false);
    const toggleCheckAns = () => {
        setCheckAns(true);
    }

    const generateRandom = () => {
        let string = ""
        for (let i = 0 ; i < 20  ; i++) {
            let random = Math.floor(Math.random() * 10);
            string += random.toString();
        }
        return parseInt(string, 10);
    }
    const answer = useMemo(() => generateRandom(), )
    let attempt = null;
    const handleAttempt = (n) => attempt = n;

    return (
        <div className='main'>
            <Question isMemorising = {isMemorising} string = {string}/>
            <div className = "second_layer">
                <Bar isMemorising = {isMemorising} isDone = {checkAns} handleAttempt = {handleAttempt}/>
                {isMemorising ? <button className='button' onClick={toggleIsMemorising}> Start </button> 
                :<button className='button' onClick={toggleCheckAns}> Done </button>}
            </div>
        </div>

    )
}

export default Main;
